export default function c(a){const r=[...a.querySelectorAll('a[href^="#"]')],s=r.map(e=>({link:e,target:document.getElementById(e.getAttribute("href").slice(1))})).filter(e=>e.target);if(a.classList.add("las-tabs-ready"),!s.length||!("IntersectionObserver"in window))return;const n=e=>{r.forEach(t=>t.classList.toggle("is-active",t===e))};n(r[0]);const i=new IntersectionObserver(e=>{e.forEach(t=>{t.isIntersecting&&n(s.find(o=>o.target===t.target).link)})},{rootMargin:"-20% 0px -70% 0px"});s.forEach(e=>i.observe(e.target))}
